	}
	deals[id] = &Escrow{
		Buyer:  buyer,
		Seller: seller,
		Amount: amount,
	}
}

func ReleaseFunds(id, caller string) {
	d, ok := deals[id]
	if !ok {
		panic("deal not found")
	}
	if caller != d.Buyer {
		panic("only buyer can release")
	}
	d.Release = true
}

