	out := "escrow deals:\n"
	for id, d := range deals {
		status := "pending"
		if d.Release {
			status = "released"
		}
		out += "  " + id + " (" + strconv.Itoa(int(d.Amount)) + ") " + status + "\n"
	}
	return out
}

