	tickets[player]++
	return tickets[player]
}

func Draw(_ realm) string {
	if drawCalled {
		panic("already drawn")
	}
	drawCalled = true
	max := 0
	for p, t := range tickets {
		if t > max {
			max = t
			winner = p
		}
	}
	return winner
}

func Render(_ string) string {
	out := "CRAZY LOTTERY\n"
	out += "players: " + strconv.Itoa(len(tickets)) + "\n"
