// dao — Decentralized Autonomous Organization governance system
// Features: Proposal creation, voting with quorum, timelock execution
package dao

import (
	"strconv"
	"strings"

	"chain/runtime"
)

// Proposal states
const (
	StatusActive   = "active"
	StatusPassed   = "passed"
	StatusExecuted = "executed"
	StatusRejected = "rejected"
)

type Proposal struct {
	ID                int
	Title             string
	Description       string
	Proposer          string
	ForVotes          int
	AgainstVotes      int
	Voters            map[string]bool
	Status            string
	CreatedBlock      int64
	VotingEndBlock    int64
	ExecuteAfterBlock int64
}

var (
	proposals       map[int]*Proposal
	nextID           int
	votingPeriod     int64
	timelockPeriod   int64
	quorum           int
	totalMembers     int
	members          map[string]bool
)

func init() {
	proposals = make(map[int]*Proposal)
	nextID = 1
	votingPeriod = 100
	timelockPeriod = 50
	quorum = 5
	totalMembers = 0
	members = make(map[string]bool)
}

// === Membership ===

func AddMember(cur realm, member string) {
	caller := cur.Previous().Address().String()
	if totalMembers > 0 && !members[caller] {
		panic("only DAO members can add new members")
	}
	if members[member] {
		panic("already a member")
	}
	members[member] = true
	totalMembers++
}

func IsMember(addr string) bool {
	return members[addr]
}

func MemberCount() int {
	return totalMembers
}

// === Proposal Lifecycle ===

func CreateProposal(cur realm, title, description string) int {
	caller := cur.Previous().Address().String()
	if !members[caller] {
		panic("only DAO members can create proposals")
	}

	id := nextID
	nextID++
	currentBlock := runtime.ChainHeight()

	proposals[id] = &Proposal{
		ID:                id,
		Title:             title,
		Description:       description,
		Proposer:          caller,
		Voters:            make(map[string]bool),
		Status:            StatusActive,
		CreatedBlock:      currentBlock,
		VotingEndBlock:    currentBlock + votingPeriod,
		ExecuteAfterBlock: currentBlock + votingPeriod + timelockPeriod,
	}
	return id
}

func Vote(cur realm, proposalID int, support bool) {
	caller := cur.Previous().Address().String()
	if !members[caller] {
		panic("only DAO members can vote")
	}

	p, ok := proposals[proposalID]
	if !ok {
		panic("proposal not found")
	}
	if p.Status != StatusActive {
		panic("voting not active")
	}
	if runtime.ChainHeight() > p.VotingEndBlock {
		panic("voting period ended")
	}
	if p.Voters[caller] {
		panic("already voted")
	}

	p.Voters[caller] = true
	if support {
		p.ForVotes++
	} else {
		p.AgainstVotes++
	}
}

func FinalizeProposal(cur realm, proposalID int) string {
	p, ok := proposals[proposalID]
	if !ok {
		panic("proposal not found")
	}
	if p.Status != StatusActive {
		return p.Status
	}
	if runtime.ChainHeight() <= p.VotingEndBlock {
		panic("voting period not ended")
	}

	totalVotes := p.ForVotes + p.AgainstVotes
	if totalVotes < quorum {
		p.Status = StatusRejected
		return StatusRejected
	}
	if p.ForVotes > p.AgainstVotes {
		p.Status = StatusPassed
		return StatusPassed
	}
	p.Status = StatusRejected
	return StatusRejected
}

func ExecuteProposal(cur realm, proposalID int) string {
	p, ok := proposals[proposalID]
	if !ok {
		panic("proposal not found")
	}
	if p.Status != StatusPassed {
		panic("proposal not passed")
	}
	if runtime.ChainHeight() < p.ExecuteAfterBlock {
		remaining := p.ExecuteAfterBlock - runtime.ChainHeight()
		panic("timelock not expired - wait " + strconv.FormatInt(remaining, 10) + " blocks")
	}
	p.Status = StatusExecuted
	return StatusExecuted
}

// === Query Functions ===

func GetProposal(id int) (string, string, string, string, int, int, int, int64) {
	p := proposals[id]
	return p.Title, p.Description, p.Proposer, p.Status,
		p.ForVotes, p.AgainstVotes, len(p.Voters), p.ExecuteAfterBlock
}

func ProposalCount() int {
	return len(proposals)
}

func GetConfig() (int64, int64, int, int) {
	return votingPeriod, timelockPeriod, quorum, totalMembers
}

func SetConfig(cur realm, voting, timelock, quorumNeeded int64) {
	caller := cur.Previous().Address().String()
	if !members[caller] {
		panic("only members can update config")
	}
	votingPeriod = voting
	timelockPeriod = timelock
	quorum = int(quorumNeeded)
}

// === Render ===

func Render(_ string) string {
	b := strings.Builder{}
	b.WriteString("# DAO Governance\n\n")
	b.WriteString("## Config\n")
	b.WriteString("- Voting Period: " + strconv.FormatInt(votingPeriod, 10) + " blocks\n")
	b.WriteString("- Timelock: " + strconv.FormatInt(timelockPeriod, 10) + " blocks\n")
	b.WriteString("- Quorum: " + strconv.Itoa(quorum) + " votes\n")
	b.WriteString("- Members: " + strconv.Itoa(totalMembers) + "\n\n")
	b.WriteString("## Proposals (" + strconv.Itoa(len(proposals)) + ")\n")
	for id, p := range proposals {
		b.WriteString("### #" + strconv.Itoa(id) + " " + p.Title + "\n")
		b.WriteString("- Status: " + p.Status + "\n")
		b.WriteString("- For: " + strconv.Itoa(p.ForVotes) + " | Against: " + strconv.Itoa(p.AgainstVotes) + "\n")
		b.WriteString("- Voters: " + strconv.Itoa(len(p.Voters)) + "\n")
		b.WriteString("- Execute after block: " + strconv.FormatInt(p.ExecuteAfterBlock, 10) + "\n\n")
	}
	return b.String()
}

// multisig — Multi-signature wallet (Gno Safe)
// Requires M-of-N signatures to execute transactions
// 10 signers, 7 required threshold
package multisig

import (
	"strconv"
	"strings"

	"chain/runtime"
)

// Tx represents a pending multi-sig transaction
type Tx struct {
	ID         int
	To         string  // recipient address
	Amount     int64   // amount in ugnot
	Proposer   string  // who submitted
	Approved   map[string]bool  // who approved
	Executed   bool
	CreatedBlock int64
}

var (
	transactions map[int]*Tx
	nextTxID     int
	signers      map[string]bool
	threshold    int  // signatures needed
	totalSigners int
)

func init() {
	transactions = make(map[int]*Tx)
	nextTxID = 1
	signers = make(map[string]bool)
	threshold = 7
	totalSigners = 0
}

// === Signer Management ===

// AddSigner adds a new signer. Only existing signers can add.
func AddSigner(cur realm, signer string) {
	caller := cur.Previous().Address().String()
	if totalSigners > 0 && !signers[caller] {
		panic("only existing signers can add new signers")
	}
	if signers[signer] {
		panic("already a signer")
	}
	signers[signer] = true
	totalSigners++
}

// IsSigner checks if address is a signer
func IsSigner(addr string) bool {
	return signers[addr]
}

// SignerCount returns total signers
func SignerCount() int {
	return totalSigners
}

// GetThreshold returns required signatures
func GetThreshold() int {
	return threshold
}

// SetThreshold updates the threshold. Only signers can do this.
func SetThreshold(cur realm, newThreshold int) {
	caller := cur.Previous().Address().String()
	if !signers[caller] {
		panic("only signers can update threshold")
	}
	if newThreshold < 1 || newThreshold > totalSigners {
		panic("invalid threshold")
	}
	threshold = newThreshold
}

// === Transaction Lifecycle ===

// SubmitTx proposes a new transaction to send ugnot
func SubmitTx(cur realm, to string, amount int64) int {
	caller := cur.Previous().Address().String()
	if !signers[caller] {
		panic("only signers can submit transactions")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}

	id := nextTxID
	nextTxID++

	transactions[id] = &Tx{
		ID:           id,
		To:           to,
		Amount:       amount,
		Proposer:     caller,
		Approved:     make(map[string]bool),
		Executed:     false,
		CreatedBlock: runtime.ChainHeight(),
	}

	// Proposer auto-approves their own submission
	transactions[id].Approved[caller] = true
	return id
}

// ApproveTx signs/approves a pending transaction
func ApproveTx(cur realm, txID int) int {
	caller := cur.Previous().Address().String()
	if !signers[caller] {
		panic("only signers can approve")
	}

	tx, ok := transactions[txID]
	if !ok {
		panic("transaction not found")
	}
	if tx.Executed {
		panic("transaction already executed")
	}
	if tx.Approved[caller] {
		panic("already approved")
	}

	tx.Approved[caller] = true
	return len(tx.Approved)
}

// ExecuteTx executes the transaction if threshold met
func ExecuteTx(cur realm, txID int) string {
	caller := cur.Previous().Address().String()
	if !signers[caller] {
		panic("only signers can execute")
	}

	tx, ok := transactions[txID]
	if !ok {
		panic("transaction not found")
	}
	if tx.Executed {
		panic("already executed")
	}

	approvalCount := len(tx.Approved)
	if approvalCount < threshold {
		panic("insufficient approvals: " + strconv.Itoa(approvalCount) + "/" + strconv.Itoa(threshold))
	}

	// Mark as executed
	// In production, this would use chain/banker to actually send ugnot
	tx.Executed = true
	return "executed: sent " + strconv.FormatInt(tx.Amount, 10) + "ugnot to " + tx.To
}

// === Query Functions ===

// GetTx returns transaction details
func GetTx(id int) (string, int64, string, int, bool, int64) {
	tx := transactions[id]
	return tx.To, tx.Amount, tx.Proposer, len(tx.Approved), tx.Executed, tx.CreatedBlock
}

// GetApprovals returns list of approvers
func GetApprovals(id int) []string {
	tx := transactions[id]
	approvers := make([]string, 0, len(tx.Approved))
	for addr := range tx.Approved {
		approvers = append(approvers, addr)
	}
	return approvers
}

// PendingTxCount returns number of pending (non-executed) txs
func PendingTxCount() int {
	count := 0
	for _, tx := range transactions {
		if !tx.Executed {
			count++
		}
	}
	return count
}

// TotalTxCount returns total transactions
func TotalTxCount() int {
	return len(transactions)
}

// === Render ===

func Render(_ string) string {
	b := strings.Builder{}
	b.WriteString("# Multi-sig Wallet (Gno Safe)\n\n")
	b.WriteString("## Config\n")
	b.WriteString("- Signers: " + strconv.Itoa(totalSigners) + "\n")
	b.WriteString("- Threshold: " + strconv.Itoa(threshold) + " signatures required\n")
	b.WriteString("- Pending TXs: " + strconv.Itoa(PendingTxCount()) + "\n\n")
	b.WriteString("## Transactions\n")
	for id, tx := range transactions {
		status := "pending"
		if tx.Executed {
			status = "executed"
		}
		b.WriteString("### TX #" + strconv.Itoa(id) + "\n")
		b.WriteString("- To: " + tx.To + "\n")
		b.WriteString("- Amount: " + strconv.FormatInt(tx.Amount, 10) + " ugnot\n")
		b.WriteString("- Proposer: " + tx.Proposer + "\n")
		b.WriteString("- Approvals: " + strconv.Itoa(len(tx.Approved)) + "/" + strconv.Itoa(threshold) + "\n")
		b.WriteString("- Status: " + status + "\n\n")
	}
	return b.String()
}

// dex — Decentralized Exchange (mini DEX)
// Features: Add liquidity, swap tokens, price discovery via x*y=k
// 10 wallets can be liquidity providers
package dex

import (
	"strconv"
	"strings"

)

// Pool represents a liquidity pool for token A / token B
type Pool struct {
	ReserveA     int64
	ReserveB     int64
	TotalLP      int64           // total liquidity provider shares
	LPShares     map[string]int64 // LP shares per address
}

// SwapResult represents the result of a swap
type SwapResult struct {
	AmountOut   int64
	NewReserveA int64
	NewReserveB int64
}

var pool *Pool

// Fee in basis points (0.3% = 30 bps)
const feeBps = 30

func init() {
	pool = &Pool{
		LPShares: make(map[string]int64),
	}
}

// === Liquidity ===

// AddLiquidity adds token A and B to the pool, returns LP shares
func AddLiquidity(cur realm, amountA, amountB int64) int64 {
	caller := cur.Previous().Address().String()
	if amountA <= 0 || amountB <= 0 {
		panic("amounts must be positive")
	}

	var shares int64
	if pool.TotalLP == 0 {
		// First liquidity: shares = sqrt(amountA * amountB)
		shares = sqrtApprox(amountA * amountB)
	} else {
		// Subsequent: shares = min(amountA * TotalLP / ReserveA, amountB * TotalLP / ReserveB)
		sharesA := amountA * pool.TotalLP / pool.ReserveA
		sharesB := amountB * pool.TotalLP / pool.ReserveB
		if sharesA < sharesB {
			shares = sharesA
		} else {
			shares = sharesB
		}
	}

	pool.ReserveA += amountA
	pool.ReserveB += amountB
	pool.TotalLP += shares
	pool.LPShares[caller] += shares

	return shares
}

// RemoveLiquidity removes liquidity and returns token amounts
func RemoveLiquidity(cur realm, shares int64) (int64, int64) {
	caller := cur.Previous().Address().String()
	if shares <= 0 {
		panic("shares must be positive")
	}
	if pool.LPShares[caller] < shares {
		panic("insufficient shares")
	}

	amountA := shares * pool.ReserveA / pool.TotalLP
	amountB := shares * pool.ReserveB / pool.TotalLP

	pool.ReserveA -= amountA
	pool.ReserveB -= amountB
	pool.TotalLP -= shares
	pool.LPShares[caller] -= shares

	return amountA, amountB
}

// === Swap ===

// SwapAForB swaps token A for token B
func SwapAForB(cur realm, amountIn int64) int64 {
	if amountIn <= 0 {
		panic("amount must be positive")
	}
	if pool.ReserveA == 0 || pool.ReserveB == 0 {
		panic("pool empty")
	}

	// Apply fee: amountInWithFee = amountIn * (10000 - feeBps)
	amountInWithFee := amountIn * (10000 - feeBps)

	// amountOut = amountInWithFee * ReserveB / (ReserveA * 10000 + amountInWithFee)
	amountOut := amountInWithFee * pool.ReserveB / (pool.ReserveA*10000 + amountInWithFee)

	if amountOut >= pool.ReserveB {
		panic("insufficient liquidity")
	}

	pool.ReserveA += amountIn
	pool.ReserveB -= amountOut

	return amountOut
}

// SwapBForA swaps token B for token A
func SwapBForA(cur realm, amountIn int64) int64 {
	if amountIn <= 0 {
		panic("amount must be positive")
	}
	if pool.ReserveA == 0 || pool.ReserveB == 0 {
		panic("pool empty")
	}

	amountInWithFee := amountIn * (10000 - feeBps)
	amountOut := amountInWithFee * pool.ReserveA / (pool.ReserveB*10000 + amountInWithFee)

	if amountOut >= pool.ReserveA {
		panic("insufficient liquidity")
	}

	pool.ReserveB += amountIn
	pool.ReserveA -= amountOut

	return amountOut
}

// === Query Functions ===

// GetReserves returns current pool reserves
func GetReserves() (int64, int64) {
	return pool.ReserveA, pool.ReserveB
}

// GetPrice returns the price of A in terms of B
func GetPrice() string {
	if pool.ReserveA == 0 {
		return "0"
	}
	price := pool.ReserveB * 1000000 / pool.ReserveA
	return strconv.FormatInt(price, 10)
}

// GetLPShares returns LP shares for an address
func GetLPShares(addr string) int64 {
	return pool.LPShares[addr]
}

// TotalLiquidity returns total LP shares
func TotalLiquidity() int64 {
	return pool.TotalLP
}

// GetAmountOut calculates expected output for a given input (read-only)
func GetAmountOut(amountIn int64, isAForB bool) int64 {
	if amountIn <= 0 {
		return 0
	}
	amountInWithFee := amountIn * (10000 - feeBps)
	if isAForB {
		if pool.ReserveA == 0 {
			return 0
		}
		return amountInWithFee * pool.ReserveB / (pool.ReserveA*10000 + amountInWithFee)
	}
	if pool.ReserveB == 0 {
		return 0
	}
	return amountInWithFee * pool.ReserveA / (pool.ReserveB*10000 + amountInWithFee)
}

// === Render ===

func Render(_ string) string {
	b := strings.Builder{}
	b.WriteString("# DEX Mini\n\n")
	b.WriteString("## Pool\n")
	b.WriteString("- Reserve A: " + strconv.FormatInt(pool.ReserveA, 10) + "\n")
	b.WriteString("- Reserve B: " + strconv.FormatInt(pool.ReserveB, 10) + "\n")
	b.WriteString("- Total LP: " + strconv.FormatInt(pool.TotalLP, 10) + "\n")
	b.WriteString("- Price (A→B): " + GetPrice() + "\n")
	b.WriteString("- Fee: 0.3%\n\n")
	b.WriteString("## Functions\n")
	b.WriteString("- `AddLiquidity(amountA, amountB)` — add liquidity\n")
	b.WriteString("- `RemoveLiquidity(shares)` — remove liquidity\n")
	b.WriteString("- `SwapAForB(amountIn)` — swap A for B\n")
	b.WriteString("- `SwapBForA(amountIn)` — swap B for A\n")
	b.WriteString("- `GetReserves()` — check pool reserves\n")
	b.WriteString("- `GetAmountOut(amountIn, isAForB)` — calculate output\n")
	return b.String()
}

// === Helpers ===

// sqrtApprox returns an approximate square root using Newton's method
func sqrtApprox(n int64) int64 {
	if n <= 0 {
		return 0
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

package pearl_token

